#!/usr/bin/env python3
"""histscan: git-history secret scanner.

Walks every commit of a repository (git rev-list + git show) and reports
secrets that were EVER committed, even if they were later removed.
"""
import argparse
import re
import subprocess
import sys

RULES = [
    ("aws-key", re.compile(r"AKIA[0-9A-Z]{16}")),
    ("api-key", re.compile(r"api[_-]?key\s*[:=]\s*['\"][A-Za-z0-9]{16,}['\"]", re.IGNORECASE)),
]


def run_git(repo: str, *args: str) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["git", "-C", repo] + list(args),
        capture_output=True,
        text=True,
        check=False,
    )


def mask(match_text: str) -> str:
    """Keep first 4 and last 4 chars; mask the middle with asterisks."""
    if len(match_text) <= 8:
        return "*" * len(match_text)
    return match_text[:4] + "*" * (len(match_text) - 8) + match_text[-4:]


def scan_repo(repo: str):
    """Yield dicts: {commit, file, rule, match} for every secret found in history."""
    rev = run_git(repo, "rev-list", "--all", "--reverse")
    if rev.returncode != 0:
        raise RuntimeError(f"git rev-list failed in {repo}: {rev.stderr.strip()}")
    commits = rev.stdout.split()

    seen_per_commit = set()
    for commit in commits:
        show = run_git(
            repo, "show", "--format=%H %h", "--unified=0", "--no-color", commit
        )
        if show.returncode != 0:
            raise RuntimeError(f"git show failed for {commit}: {show.stderr.strip()}")
        lines = show.stdout.splitlines()
        if not lines:
            continue
        header, full_hash, short_sha = None, None, None
        current_file = None
        for line in lines:
            m = re.match(r"^([0-9a-f]{40}) ([0-9a-f]+)$", line)
            if m and header is None:
                header = line
                full_hash, short_sha = m.group(1), m.group(2)
                continue
            fm = re.match(r"^\+\+\+ b/(.*)$", line)
            if fm:
                current_file = fm.group(1)
                continue
            # only inspect added lines (secrets introduced by this commit)
            if not line.startswith("+") or line.startswith("+++"):
                continue
            body = line[1:]
            for rule_name, pattern in RULES:
                for mm in pattern.finditer(body):
                    key = (full_hash, current_file, rule_name, mm.group(0))
                    if key in seen_per_commit:
                        continue
                    seen_per_commit.add(key)
                    yield {
                        "commit": short_sha,
                        "file": current_file,
                        "rule": rule_name,
                        "match": mask(mm.group(0)),
                    }


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Scan full git history for secrets.")
    ap.add_argument("repo", nargs="?", default=".", help="Path to git repository")
    args = ap.parse_args(argv)

    try:
        findings = list(scan_repo(args.repo))
    except Exception as exc:  # noqa: BLE001
        print(f"error: {exc}", file=sys.stderr)
        return 2

    for f in findings:
        print(f"{f['commit']}\t{f['file']}\t{f['rule']}\t{f['match']}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

